class Solution {public:
 int maxSumDistinctTriplet(vector<int>& x,vector<int>& y){
  unordered_map<int,int> best;for(int i=0;i<(int)x.size();++i)best[x[i]]=max(best.count(x[i])?best[x[i]]:INT_MIN,y[i]);
  if(best.size()<3)return -1;vector<int> v;for(auto &p:best)v.push_back(p.second);
  sort(v.rbegin(),v.rend());return v[0]+v[1]+v[2];
 }
};
